/** Exact-match helper: does an error message carry this path prefix?
 * Server messages are `"<Path>: <prose>"`; matching on the delimited
 * prefix keeps `Usage.Forbidden` from matching `Usage.ForbiddenExtra`. */
export function errorPathMatches(message: string, path: string): boolean {
  return message === path || message.startsWith(`${path}:`);
}
